def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    total_opp_c = 0
    for p in history:
        if p[1] == 'C':
            total_opp_c += 1
    total_opp_d = n - total_opp_c

    start = n - 10
    if start < 0:
        start = 0
    recent_opp_c = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
    recent_len = n - start
    recent_opp_d = recent_len - recent_opp_c

    opp_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_d_streak += 1
        i -= 1

    opp_c_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'C':
        opp_c_streak += 1
        i -= 1

    my_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        my_d_streak += 1
        i -= 1

    pre_c_streak = 0
    if opp_d_streak:
        j = n - opp_d_streak - 1
        while j >= 0 and history[j][1] == 'C':
            pre_c_streak += 1
            j -= 1

    provoked = False
    if opp_d_streak:
        k = n - opp_d_streak - 1
        provoked = (k >= 0 and history[k][0] == 'D')

    tft_like = False
    if n >= 6:
        mirror_hits = 0
        for i in range(1, n):
            if history[i][1] == history[i - 1][0]:
                mirror_hits += 1
        tft_like = mirror_hits >= (n - 1) * 0.55

    if total_opp_d == n and n >= 1:
        return 'D'
    if total_opp_c == n and n >= 12:
        return 'D'
    if n == 100:
        return 'D'

    if opp_last == 'D':
        if total_opp_c == 0:
            return 'D'

        if provoked and tft_like:
            if opp_d_streak <= 2:
                return 'C'
            if (
                opp_d_streak <= 4
                and pre_c_streak >= 8
                and total_opp_c >= total_opp_d + 8
                and recent_opp_c >= 6
            ):
                return 'C'
            return 'D'

        if opp_d_streak == 1:
            if recent_opp_c >= 7:
                return 'C'
            if pre_c_streak >= 5 and total_opp_c >= total_opp_d + 5:
                return 'C'
            if n <= 5 and total_opp_c >= total_opp_d:
                return 'C'
            return 'D'

        if opp_d_streak == 2:
            if (
                pre_c_streak >= 15
                and total_opp_c >= total_opp_d + 10
                and recent_opp_c >= 7
            ):
                return 'C'
            return 'D'

        if opp_d_streak == 3:
            return 'D'

        if opp_d_streak == 4:
            if pre_c_streak >= 4:
                return 'C'
            return 'D'

        return 'D'

    if my_last == 'D':
        return 'D'

    if (
        n >= 15
        and total_opp_c > total_opp_d
        and recent_opp_c >= 6
        and opp_c_streak >= 3
        and not tft_like
    ):
        return 'D'

    if n >= 97 and not tft_like and total_opp_c > total_opp_d:
        return 'D'

    return 'C'
